# 628. Maximum Product of Three Numbers
class Solution:
    def maximumProduct(self, nums: list[int]) -> int:  #T O(n), S O(1)
	   #maxProducts = max(min1 * min2 * max1, max1 * max2 * max3) (when min1,min2 is a large negative.
        min1, min2 = float('inf'), float('inf')
        max1, max2, max3 = float('-inf'), float('-inf'), float('-inf')

        for n in nums:
            # Track two smallest values
            if n <= min1:
                min2, min1 = min1, n
            elif n <= min2: min2 = n
            # Track three largest values
            if n >= max1:
                max3, max2, max1 = max2, max1, n
            elif n >= max2:
                max3, max2 = max2, n
            elif n >= max3: max3 = n
        return max(min1 * min2 * max1, max1 * max2 * max3)

# sorted rotated array, no duplicate
class Solution:
    def search(self, nums: List[int], target: int) -> int:
        l, r = 0, len(nums) - 1
        while l < r:
            mid = l + (r-l)//2
            # right half not sorted -> left half must sorted
            if nums[r] < nums[mid]:
                if nums[l] <= target <= nums[mid]: # target in sorted [left, mid]
                    r = mid # save candidate
                else:
                    l = mid + 1 
            else: # right half sorted
                if target <= nums[mid] or target > nums[r]: # target on left half, sorted or not sorted
                    r = mid
                else:
                    l = mid + 1
        return l if nums[l] == target else -1

