# 69. Sqrt(x) - Example of Maximum
class Solution:
    def mySqrt(self, x: int) -> int:
        # find MAX element a, meets: a <= target => should do right pref
        # => r = mid-1, l = mid => mid must pref right to prevent inf loop
        l, r = 0, x
        while l < r:
            mid = r - (r-l)//2 # #10
            exp = mid*mid
            if exp > x: 
                r = mid - 1 #larger, must exclude mid
            else:
                l = mid
        return l
