def peakIndexInMountainArray(arr: List[int]) -> int:
        l, r = 0, len(arr) - 1
        while l < r:
            mid = (l + r)//2
            if arr[mid] > arr[mid+1]: # 🔥Compare to right nei only, no need to check left nei arr[mid-1] <= arr[mid]. this must already happened, else arr[mid-1] must have been peak and returned
                r = mid  # save candidate
            else:
                l = mid + 1
        return l

class Solution:
    def countLessEqual(self, matrix, mid, smaller, larger):

        count, n = 0, len(matrix)
        row, col = n - 1, 0

        while row >= 0 and col < n:
            if matrix[row][col] > mid:
                # As matrix[row][col] is bigger than the mid, let's keep track of the
                # smallest number greater than the mid
                larger = min(larger, matrix[row][col])
                row -= 1
            else:

                # As matrix[row][col] is less than or equal to the mid, let's keep track of the
                # biggest number less than or equal to the mid

                smaller = max(smaller, matrix[row][col])
                count += row + 1
                col += 1

        return count, smaller, larger

    def kthSmallest(self, matrix: List[List[int]], k: int) -> int:

        n = len(matrix)
        start, end = matrix[0][0], matrix[n - 1][n - 1]
        while start < end:
            mid = start + (end - start) / 2
            smaller, larger = (matrix[0][0], matrix[n - 1][n - 1])

            count, smaller, larger = self.countLessEqual(matrix, mid, smaller, larger)

            if count == k:
                return smaller
            if count < k:
                start = larger  # search higher
            else:
                end = smaller  # search lower

        return start

# Use history array where history[i] is a list records [snapID, valAtSnapID] ith. Use binSearch on history[i], to find the most recent up to snapID time (rightmost)
class SnapshotArray:

    def __init__(self, length: int):
        self.history = [[[-1, 0]] for _ in range(length)]
        self.snapID = 0
    def set(self, index: int, val: int) -> None:
        #If you set the same index multiple times before calling snap, you can overwrite last instead of appending:
        self.history[index].append([self.snapID, val]) #main point
    def snap(self) -> int:
        self.snapID += 1
        return self.snap-1
    def get(self, index: int, snap_id: int) -> int:
        #find the most recent up to (right before or equal to) snapID time (rightmost)
        l, r = 0, len(self.history[index])-1
        while l < r:
            mid = r-(r-l)//2
            if self.history[index][mid][0] <= snap_id:
                l = mid
            else:
                r = mid - 1
        return self.history[index][l][1]

def platesBetweenCandles(s, queries):
    n = len(s)
    nearLeft = [-1] * n #nearest candleIdx on the left(inclu) of i in s
    nearRight = [-1] * n # nearest candle on the right(inclu)
    candleCounts = [0]*n

    candleCounts[0] = 1 if s[0] == '|' else 0
    nearLeft[0] = 0 if s[0] == '|' else -1
    nearRight[-1] = n-1 if s[-1] == '|' else -1  

    for i in range(1, n): 
        nearLeft[i] = i if s[i] == '|' else nearLeft[i-1]
        candleCounts[i] = candleCounts[i-1]+1 if s[i-1] == '|' else candleCounts[i-1]

    for i in range(n-2, -1, -1):
        nearRight[i] = i if s[i] == '|' else nearRight[i+1]

    res = []

    for qleft, qright in queries:
        # Get the one on right of qleft, and on left of qright
        leftCand, rightCand = nearRight[qleft], nearLeft[qright]
        # res = range between two outermost candles - candle count in between
        if (leftCand != -1) and (rightCand!= -1) and leftCand < rightCand:
            res.append(( rightCand - leftCand -1) - (candleCounts[rightCand] - candleCounts[leftCand] -1))
        else:
            res.append(0)
    return res
#Approach: Get array of candleIdx; binSearch leftmost candles => qleft, rightmost candle <= qright
def platesBetweenCandles(s, queries):
    # candleIdx array, ofc sorted
    candles = [i for i in len(s) if s[i]=='i' ] 

    res = []
    def bisectLeft(arr, x): # return position of "x" in arr (leftest preferred)
        l, r = 0, len(arr)
        while l < r:
            mid = l + (r-l)//2
            if arr[mid] >= x:
                r = mid
            else:
                l = mid + 1
        return l

    for qleft, qright in queries:
        # 1. find index of first candle that comes after qleft (leftmost)
        left_pos = bisectLeft(candles, qleft)
        # 2. find index of last candle that comes before qright (rightmost)
        right_pos= bisectLeft(candles, qright+1) - 1 # get leftest of [qright+1] => rightmost(qright) is on the left (idx-1)

        # 3. result = range between two outermost candles - candle count in between
        if (left_pos != -1) and (right_pos!= -1) and (right_pos > left_pos):
            res.append((candles[right_pos] - candles[left_pos]-1) - (right_pos - left_pos-1))
        else:
            res.append(0)
    return res
