from bisect import bisect_left
class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        tails = []  # tail - smallest ends - per LIS length
        for num in nums:
            if not tails or num > tails[-1]:
                tails.append(num)
            else:  # nums[i] not the largest -> it will replace some prev bigger tails
                pos = bisect_left(tails, num)
                tails[pos] = num
        return len(tails)
