def subarray_sum_shortest(nums: list[int], target: int) -> int:
    l = 0
    shortest = -1
    tempSum=0
    for r in range(len(nums)):
        tempSum += nums[r]
        while tempSum-nums[l] >= target:
            tempSum -= nums[l]
            l+=1
        if tempSum >= target:
            shortest=min(shortest, r-l+1) if shortest != -1 else r-l+1
    return shortest
