from collections import OrderedDict
def maxDepth(root: Optional[TreeNode]) -> int:
    if not root:
        return 0
    maxDepth = 1
    stack = [[root, 1]]
    while stack:
        node, nodeDepth = stack.pop()
        if node:
            stack.append([node.left, nodeDepth+1])
            stack.append([node.right, nodeDepth+1])
            maxDepth = max(maxDepth, nodeDepth)
    return maxDepth

