def lowestCommonAncestor(root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':
    greater = max( p.val, q.val)
    smaller = min(q.val, p.val) 
    cur = root
    while cur:
        if smaller <= cur.val and cur.val <= greater:
            return cur
        elif cur.val > greater:
            cur = cur.left
        elif cur.val < smaller:
            cur = cur.right 
    return cur

