def closestKValues(root, target, k):
    stack = []
    node = root
    queue = deque()
    while stack or node:
        while node: # 1. Reach the leftmost node
            stack.append(node)
            node = node.left

        node = stack.pop()          # 2. Process the node
        queue.append(node.val)       # visit
        if len(queue) > k: # ⭐️ Cut front or back to keep k-sized queue 
            if abs(target-queue[-1]) < abs(target-queue[0]): 
                queue.popleft()
            else: 
                queue.pop() # addedNum too far, stop go further
                break

        node = node.right

    return list(queue)

# Use deque as curPath to appendleft value of nodes with O(1) for reversed levels
def zigzagLevelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
    if not root: return []
    forward = True
    queue = deque([root])
    res = []
    #add to queue as normal, it's just if it's a backward, when append val to result -> appendleft.
    while queue:
        n = len(queue)
        path = deque()
        for _ in range(n):
            node = queue.popleft()
            if forward:
                path.append(node.val)
            else:
                path.appendleft(node.val)
            for child in [node.left, node.right]:
                if child:
                    queue.append(child)
        forward = not forward
        res.append(list(path))

    return res
# 111. Minimum Depth of Binary Tree
def minDepth(root: Optional[TreeNode]) -> int:
    queue = deque([root])
    level = 1
    while queue:
        n = len(queue)
        for _ in range(n):
            node = queue.popleft()
            for child in [node.left, node.right]:
                if child:
                    if not child.left and not child.right:
                        return level
                    queue.append(child)
        level+=1
    return level

