class Solution:
    def findWords(self,board: list[list[str]], words: list[str]) -> list[str]:
        mtrie = Trie()
        for word in words:
            mtrie.insert(word)
        res, visit = set(), set()
        ROW, COL = len(board), len(board[0])

        def dfssearch(ro, co, cur, formingWord): #cur in Trie, examine child char=[ro][co]
            if (ro not in range(ROW) or co not in range(COL) #out of bound 
            or (ro, co) in visit #visited
            or board[ro][co] not in cur.children #not the right char square
            or cur.children[board[ro][co]].ref < 1): #if already found and removed
                return

            visit.add((ro,co)) # Start backtrack
            formingWord += board[ro][co]
            cur = cur.children[board[ro][co]]

            if cur.isWord: # remove word from Trie if found
                res.add(formingWord)
                mtrie.removeWord(formingWord)

            dfssearch(ro+1, co, cur, formingWord)
            dfssearch(ro-1, co, cur, formingWord)
            dfssearch(ro, co+1, cur, formingWord)
            dfssearch(ro, co-1, cur, formingWord)

            visit.remove((ro,co)) # Revert backtrack
        for ro in range(ROW):
            for co in range(COL):
                dfssearch(ro,co, mtrie.root, "")
        return list(res)

