from collections import defaultdict, deque
class Solution:
    def findOrder(self, numCourses: int, prerequisites: list[list[int]]) -> list[int]:
        topo = []
        indegree = [0]*numCourses
        graph = defaultdict(list)
        q = deque()
        # 1. Get inindegrees and init graph
        for des, src in prerequisites:
            indegree[des] += 1
            graph[src].append(des)
        # 2. Init Q with 0-indegree
        for node in range(numCourses):
            if indegree[node] == 0:
                q.append(node)
        # 3. Go through Q, -1 each visit of non-0 indegree child, add to res and Q if child.indegree = 0
        while q:
            popNode = q.popleft()
            topo.append(popNode)
            for child in graph[popNode]:
                indegree[child] -= 1
                if indegree[child] == 0:
                    q.append(child)

        return topo if len(topo) == numCourses else []
