class Solution:
    def findOrder(self, numCourses: int, prerequisites: list[list[int]]) -> list[int]:
        topo = []
        topoSet, visitPath = set(), set() # topoSet: nodes in topo order, visitPath: nodes in current path
        graph = defaultdict(list)
        for des, src in prerequisites:
            graph[src].append(des)
        def dfs(node):
            if node in topoSet: return True # ⛔️ already in topo -> True 
            if node in visitPath: return False # the order of these two base case is not important, because toposet nodes will never in visit path, vice versa, toposet nodes are final certified legal, never point to a cycle

            visitPath.add(node)
            for child in graph[node]:
                if not dfs(child): return False
            visitPath.remove(node)

            topo.append(node) # ⭐️ add to topo here
            topoSet.add(node)

            return True
        for node in range(numCourses):
            if not dfs(node): return []
        return topo[::-1]
class Solution:
    # Use visitSet to detect revisited node (loop)
    # Memorize prevNode when DFS each Node to prevent Node go back, only go forward
    def validTree(self, n: int, edges: list[list[int]]) -> bool:
        graph = defaultdict(list)
        visit = set()
        for n1, n2 in edges:
            graph[n1].append(n2)
            graph[n2].append(n1)

        def dfs(node, prev):
            if node in visit:
                return False
            visit.add(node)
            for child in graph[node]:
                if child != prev:  # dfs all children except prev (parent)
                    if not dfs(child, node):
                        return False
            return True
        return dfs(0, -1) and len(visit) == n


