class Solution:
    class DSU:
        def __init__(self):
            self.id = {}
            self.rank = defaultdict(int)

        def union(self, x: int, y: int) -> None:
            # by rank
            rootX, rootY = self.find(x), self.find(y)
            if rootX != rootY:
                if self.rank[rootX] > self.rank[rootY]:
                    self.id[rootY] = rootX
                else: 
                    self.id[rootX] = rootY
                    if self.rank[rootX] == self.rank[rootY]:
                        self.rank[rootY] += 1

        def find(self, node: tuple[int, int, str]) -> tuple[int, int, str]:
            parent = self.id.get(node, node)
            if parent != node: 
                self.id[node] = parent = self.find(parent)
            return parent
