# at each day, we can "reach back": dp[d]=min(dp[d-1]+2, dp[d-7]+7, dp[d-30]+15)
def mincostTickets(days: list[int], costs: list[int]) -> int:
    travelDays = set(days)  # q. Set: fast check if a date in days
    lastDay = days[-1]
    dp = [0] * (lastDay+1)  # Base: dp[0] = 0 ~ $0 for D-0
    for day in range(1, lastDay+1):
        if day not in travelDays:
            # MinCost of a non-traval day == minCost of the day before it
            dp[day] = dp[day-1]
        else:
            dp[day] = min(dp[day-1]+costs[0],
                          # minCost at 7 days ago, then buy a 7-D ticket - got used including today.
                          dp[max(0, day-7)]+costs[1],
                          dp[max(0, day-30)]+costs[2])
    return dp[lastDay]


