def minPathSum(grid: list[list[int]]) -> int:
    # use 1d dp for current row, space optimization
    # minCurCost = min(top,left) + cur
    m, n = len(grid), len(grid[0])
    dp = [0]*n
    dp[0] = grid[0][0]
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            if i == 0:    # 1. init first row
                dp[j] = dp[j-1] + grid[i][j]
            elif j == 0:  # 2. init first col
                dp[j] += grid[i][j]
            elif j > 0:   # 3. CORE: dp[cur] = curVal + min(dp[top], dp[left])
                dp[j] = grid[i][j] + min(dp[j], dp[j-1])
    return dp[-1]

