def shortestCommonSupersequence(str1: str, str2: str) -> str:
    n, m = len(str1), len(str2)
    dp = [[0] * (m+1) for _ in range(n+1)]
    if str1 == str2:
        return str1
    for i in range(n+1):
        for j in range(m+1):
            if i == 0 and j == 0:
                continue

            if i == 0:
                dp[i][j] = dp[i][j-1] + 1
            elif j == 0:
                dp[i][j] = dp[i-1][j] + 1
            else:
                if str1[i-1] == str2[j-1]:  # Match
                    dp[i][j] = dp[i-1][j-1] + 1
                else:  # Not match: minLen(choose i from top, choose j from left)
                    dp[i][j] = min(dp[i-1][j]+1, dp[i][j-1]+1)

    # ⭐️ Trace backwards
    i, j = n, m
    res = []
    while i > 0 and j > 0:
        if str1[i-1] == str2[j-1]:
            res.append(str1[i-1])
            i -= 1
            j -= 1
        else:
            if dp[i-1][j] < dp[i][j-1]:
                res.append(str1[i-1])
                i -= 1
            else:
                res.append(str2[j-1])
                j -= 1
    # Add remainings
    while i > 0:
        res.append(str1[i-1])
        i -= 1
    while j > 0:
        res.append(str2[j-1])
        j -= 1

    return "".join(res[::-1])  # reverse

