def longestStrChain(words: List[str]) -> int:
    words.sort(key=len) # bottom up from shortest
    dp = {} # {word: longestChainLen}
    for word in words:
        dp[word] = 1 # ✅ init base dp[word] = 1
        for i in range(len(word)):
