def longestStrChain(words: List[str]) -> int:
    words.sort(key=len, reverse=True) # dfs longest first, chop it off on the way
    wordSet = set(words)
    @lru_cache(None)
    def dfs(word): # visiting word
        if len(word) == 1: return 1 # base case: 1-len word
        maxLen = 1
        for i in range(len(word)): 
            choppedWord = word[:i]+word[i+1:] 
            if choppedWord in wordSet:
                maxLen = max(maxLen, 1+dfs(choppedWord))
        return maxLen

    return max(dfs(word) for word in words)

