def house_robber_iii(root: Node) -> int:
    @lru_cache
    def dfs(node: Optional[Node]) -> tuple[int, int]: # return res[0] = takeNode, res[1] = skipNode
        if not node: return (0, 0)
        left, right = dfs(node.left), dfs(node.right)

        # take node -> get children's skip
        take = node.val + left[1] + right[1]
        # skip node -> get children's take
        skip =left[0] + right[0]
        return (take, skip)
