# Use deque as curPath to appendleft value of nodes with O(1) for reversed levels
def zigzagLevelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
    if not root: return []
    forward = True
    queue = deque([root])
    res = []
    #add to queue as normal, it's just if it's a backward, when append val to result -> appendleft.
    while queue:
        n = len(queue)
        path = deque()
        for _ in range(n):
            node = queue.popleft()
            if forward:
                path.append(node.val)
            else:
                path.appendleft(node.val)
            for child in [node.left, node.right]:
                if child:
                    queue.append(child)
        forward = not forward
        res.append(list(path))

    return res
