class Solution:
    def reorganizeString(self, s: str) -> str:
        counter = [[freq, char] for char, freq in Counter(s).items()]
        counter.sort()
        n = len(s)
        res = [""] * n

        if counter[-1][0] > ceil(n/2): return ""

        # EVEN
        for i in range (0, n, 2):
            res[i] = counter[-1][1]
            counter[-1][0] -= 1
            if counter[-1][0] == 0: counter.pop()

        # ODD - same
        for i in range (1, n, 2):
            res[i] = counter[-1][1]
            counter[-1][0] -= 1
            if counter[-1][0] == 0: counter.pop()

        return "".join(res)

