def maximalNetworkRank(self, n: int, roads: list[list[int]]) -> int:
    ranks = defaultdict(int)

    for road in roads:
        ranks[road[0]] += 1
        ranks[road[1]] += 1

    maxrank = 0
    for i in range(n):
        for j in range(i + 1,  n):
            # if i,j has mutualroad, those 2 same roads counted once -> -1
            totalRank = (ranks[i] + ranks[j]) - (1 if [i, j] in roads or [j, i] in roads else 0)
            if totalRank > maxrank:
                maxrank = totalRank
    return maxrank

